import{_ as t,o as l,c as i,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"Ceph Month 2021- Call for Participation- Ceph Stable Releases Team","description":"","frontmatter":{"title":"Ceph Month 2021- Call for Participation- Ceph Stable Releases Team","date":"2021-06-01T00:00:00.000Z","updated":"2021-06-02T00:00:00.000Z","tags":["Ceph","分布式存储","稳定版本发布","社区参与","版本管理"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Month_2021_-_Call_for_Participation_-_Ceph_Stable_Releases_Team.md","filePath":"posts/2021/Ceph_Month_2021_-_Call_for_Participation_-_Ceph_Stable_Releases_Team.md","lastUpdated":1780459816000}'),s={name:"posts/2021/Ceph_Month_2021_-_Call_for_Participation_-_Ceph_Stable_Releases_Team.md"};function o(p,e,r,_,n,c){return l(),i("div",null,[...e[0]||(e[0]=[a('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题：</strong> Ceph 稳定版本发布流程及社区参与</p><p><strong>主讲人：</strong> Louis Desjardins</p><p><strong>会议概要：</strong> Louis Desjardins 介绍了 Ceph 稳定版本发布团队的工作流程，强调了社区参与的重要性，并讨论了如何优先处理回溯补丁。</p><p><strong>主要议题：</strong></p><ol><li><p><strong>Ceph 版本管理：</strong></p><ul><li>目前最新的稳定版本是 Pacific，用户在升级到 Pacific 点发布版本时，期望获得已回溯的 bug 修复和安全修复。</li><li>回溯补丁的过程涉及在旧版本上应用修复，这可能导致因代码变化而失败，需要手动调整。</li></ul></li><li><p><strong>测试流程：</strong></p><ul><li>每个回溯补丁在应用到 Pacific 之前，必须通过单元测试和大规模测试实验室的实际集群测试，以确保不会引入回归错误。</li><li>同时，还需确保 Octopus 集群可以升级到 Pacific，避免升级过程中的问题。</li></ul></li><li><p><strong>社区参与：</strong></p><ul><li>鼓励社区成员通过加入稳定版本发布团队来参与回溯补丁的工作。</li><li>新成员可以通过将感兴趣的补丁应用到 Octopus 版本，并创建 Pull Request 来开始参与。</li><li>社区提供 IRC 频道（#ceph-backports）来协助新成员解决测试失败等问题。</li></ul></li><li><p><strong>公司参与：</strong></p><ul><li>Louis 所在的公司 Easter Eggs 决定每月投入两天时间支持 Ceph 稳定版本发布团队，以回馈社区。</li></ul></li></ol><p><strong>决定事项：</strong></p><ul><li>强调了社区参与对于维护 Ceph 稳定版本的重要性，并鼓励更多公司和个人参与进来。</li></ul><p><strong>后续行动计划：</strong></p><ul><li>继续推动社区成员参与 Ceph 稳定版本发布团队，特别是通过回溯补丁的工作。</li><li>探索和优化回溯补丁的优先级策略，以更好地满足用户需求。</li></ul><p><strong>讨论问题：</strong></p><ul><li>如何优先处理回溯补丁？ <ul><li>目前没有明确的书面策略，主要依赖于紧急程度和社区的参与度。</li><li>对于某些复杂的修复，可能需要更多时间来确保其安全性，避免引入新的问题。</li></ul></li></ul><p><strong>会议结束：</strong> 感谢 Louis Desjardins 的详细介绍和解答，会议圆满结束。</p>',13)])])}const g=t(s,[["render",o]]);export{h as __pageData,g as default};
